BENCHMARK_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>10-minute transcription benchmark</title>
<style>
:root{font-family:Inter,"Segoe UI",system-ui,sans-serif;color:#17201d}body{margin:0;background:#f2f5f4}main{width:min(1150px,calc(100% - 28px));margin:24px auto}.card{background:white;border:1px solid #dce5e2;border-radius:15px;padding:18px;margin-top:14px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}button,input,select,textarea{box-sizing:border-box;width:100%;padding:8px;border:1px solid #bdcbc7;border-radius:8px;font:inherit}button{background:#196b59;color:white;border:0;font-weight:700;cursor:pointer}.secondary{background:#e7efed;color:#24443d}.danger{background:#8a3333}.segment{display:grid;grid-template-columns:90px 90px 140px 1fr 42px;gap:8px;margin:8px 0}.segment textarea{min-height:58px}.help{color:#53635e;font-size:.88rem}audio{width:100%}pre{white-space:pre-wrap;background:#f6f8f7;padding:12px;border-radius:8px}a{color:#145d4e;font-weight:700}@media(max-width:800px){.grid,.segment{grid-template-columns:1fr}.segment button{min-height:38px}}
</style></head><body><main>
<p><a href="/">← Main transcriber</a></p>
<section class="card"><h1>Permanent 10-minute accuracy benchmark</h1><p>This held-out audio is never used for training. Correct every word and speaker label; changes save automatically.</p>
<button id="prepare">Prepare the exact 10-minute set from the Mum and Wifey recordings</button><div id="status" class="help" style="margin-top:8px">Loading…</div></section>
<section class="card" id="editor" hidden><div class="grid"><div><label>Clip</label><select id="clip"></select></div><div><label><input id="loop" type="checkbox" style="width:auto"> Loop selected segment</label></div><div><button id="draft" class="secondary">Generate local draft</button></div><div><button id="add" class="secondary">Add segment</button></div></div>
<audio id="audio" controls></audio><p class="help">Shortcuts: Space play/pause, J/K previous/next segment, L toggle looping. Click a row to select it.</p><div class="segment help"><b>Start</b><b>End</b><b>Speaker</b><b>Verbatim words</b><b></b></div><div id="segments"></div></section>
<section class="card" id="evaluation" hidden><h2>Measured model evaluation</h2><p>After all six clips are corrected, this runs every installed candidate on original and conservatively processed audio. It promotes only a configuration that passes the stated gates.</p><button id="run">Run installed-model benchmark</button><pre id="report">No report yet.</pre></section>
</main><script>
const $=id=>document.getElementById(id);let data=null,current=null,rows=[],selected=0,saveTimer=null,polling=null;
function message(text){$('status').textContent=text}
async function load(){const response=await fetch('/api/benchmark/data');if(response.status===404){$('prepare').hidden=false;message('Benchmark audio has not been prepared.');return}data=await response.json();$('prepare').hidden=true;$('editor').hidden=false;$('evaluation').hidden=false;$('clip').replaceChildren();for(const item of data.items){const o=document.createElement('option');o.value=item.id;o.textContent=`${item.id} — ${item.duration.toFixed(3)}s${item.complete?' ✓':''}`;$('clip').appendChild(o)}show(data.items[0]);if(data.report)$('report').textContent=JSON.stringify(data.report,null,2);message(`${data.items.filter(x=>x.complete).length}/6 clips corrected; total ${data.duration_seconds}s.`)}
function show(item){current=item;$('clip').value=item.id;$('audio').src='/benchmark/audio/'+encodeURIComponent(item.id)+'.wav';rows=(item.gold_segments?.length?item.gold_segments:item.draft_segments?.length?item.draft_segments:[{start:0,end:item.duration,text:'',speaker:'Speaker 1'}]).map(x=>({...x}));selected=0;render()}
function render(){const root=$('segments');root.replaceChildren();rows.forEach((row,index)=>{const div=document.createElement('div');div.className='segment';div.onclick=()=>{selected=index};for(const field of ['start','end']){const input=document.createElement('input');input.type='number';input.step='.001';input.value=Number(row[field]).toFixed(3);input.oninput=()=>{row[field]=Number(input.value);schedule()};div.appendChild(input)}const speaker=document.createElement('input');speaker.value=row.speaker||'';speaker.oninput=()=>{row.speaker=speaker.value;schedule()};div.appendChild(speaker);const text=document.createElement('textarea');text.value=row.text||'';text.oninput=()=>{row.text=text.value;schedule()};div.appendChild(text);const remove=document.createElement('button');remove.textContent='×';remove.className='danger';remove.onclick=e=>{e.stopPropagation();rows.splice(index,1);render();schedule()};div.appendChild(remove);root.appendChild(div)})}
function schedule(){clearTimeout(saveTimer);saveTimer=setTimeout(save,500)}async function save(){if(!current)return;const response=await fetch('/api/benchmark/'+encodeURIComponent(current.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({segments:rows})});if(response.ok){message('Correction saved automatically.');current.gold_segments=rows;current.complete=rows.some(x=>x.text.trim())}else{const p=await response.json();message(p.error)}}
$('prepare').onclick=async()=>{message('Decoding sources and preparing exactly 600 seconds…');const response=await fetch('/api/benchmark/prepare',{method:'POST'});const p=await response.json();if(!response.ok){message(p.error);return}await load()};$('clip').onchange=()=>show(data.items.find(x=>x.id===$('clip').value));$('add').onclick=()=>{const previous=rows.at(-1);rows.push({start:previous?previous.end:0,end:Math.min(current.duration,(previous?previous.end:0)+5),speaker:previous?.speaker||'Speaker 1',text:''});render()};
$('audio').ontimeupdate=()=>{const row=rows[selected];if(row&&$('loop').checked&&$('audio').currentTime>=row.end){$('audio').currentTime=row.start;$('audio').play()}};
document.addEventListener('keydown',event=>{if(event.target.matches('input,textarea'))return;if(event.code==='Space'){event.preventDefault();$('audio').paused?$('audio').play():$('audio').pause()}else if(event.key.toLowerCase()==='j'){selected=Math.max(0,selected-1);$('audio').currentTime=rows[selected]?.start||0}else if(event.key.toLowerCase()==='k'){selected=Math.min(rows.length-1,selected+1);$('audio').currentTime=rows[selected]?.start||0}else if(event.key.toLowerCase()==='l'){$('loop').checked=!$('loop').checked}});
function poll(id,done){clearInterval(polling);polling=setInterval(async()=>{const response=await fetch('/api/jobs/'+id);const job=await response.json();message(job.message||job.status);if(job.status==='done'){clearInterval(polling);await load();if(done)done(job)}else if(job.status==='error'){clearInterval(polling);message(job.error)}},1000)}
$('draft').onclick=async()=>{const response=await fetch('/api/benchmark/'+encodeURIComponent(current.id)+'/draft',{method:'POST'});const p=await response.json();if(response.ok)poll(p.job_id);else message(p.error)};
$('run').onclick=async()=>{const response=await fetch('/api/benchmark/run',{method:'POST'});const p=await response.json();if(response.ok)poll(p.job_id,job=>{$('report').textContent=job.transcript});else message(p.error)};
load();
</script></body></html>"""
